<?php
declare(strict_types=1);

namespace App\Controllers\Admin;

use App\Core\{AppKernel,Request,Response};
use App\Domain\Inventory\InventoryRules;

final class InventoryController extends AdminController
{
    public function index(Request$r):Response
    {
        $u=$this->requireUser();if($u instanceof Response)return$u;$allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,'inventory.view');if($allowed===[])return$this->requirePermission($u,'inventory.view')??throw new \LogicException();$branch=$r->integer('branch_id')?:null;if(is_array($allowed)){if($branch!==null&&!in_array($branch,$allowed,true))return$this->requirePermission($u,'inventory.view',$branch)??throw new \LogicException();$branch??=$allowed[0]??null;}$status=$r->query('status','all');$offset=max(0,(int)$r->query('offset','0'));return$this->adminView('admin/inventory/index',['title'=>'Inventario','activeNav'=>'inventory','user'=>$u,'page'=>AppKernel::inventory()->balances(trim($r->query('q')),$branch,$status,25,$offset),'q'=>trim($r->query('q')),'branchId'=>$branch,'status'=>$status,'allBranches'=>$allowed===null,'branches'=>$this->branches($allowed)]);
    }
    public function movements(Request$r):Response
    {
        $u=$this->requireUser();if($u instanceof Response)return$u;$allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,'inventory.movements.view');if($allowed===[])return$this->requirePermission($u,'inventory.movements.view')??throw new \LogicException();$branch=$r->integer('branch_id')?:null;if(is_array($allowed)){if($branch!==null&&!in_array($branch,$allowed,true))return$this->requirePermission($u,'inventory.movements.view',$branch)??throw new \LogicException();$branch??=$allowed[0]??null;}$type=$r->query('type');$type=$type===''?null:InventoryRules::type($type);$from=$this->date($r->query('from'));$until=$this->date($r->query('until'));$offset=max(0,(int)$r->query('offset','0'));return$this->adminView('admin/inventory/movements',['title'=>'Movimientos de inventario','activeNav'=>'inventory','user'=>$u,'page'=>AppKernel::inventory()->movements(trim($r->query('q')),$branch,$r->integer('variant_id')?:null,$type,$from,$until,25,$offset),'q'=>trim($r->query('q')),'branchId'=>$branch,'variantId'=>$r->integer('variant_id')?:null,'type'=>$type,'from'=>$from,'until'=>$until,'allBranches'=>$allowed===null,'branches'=>$this->branches($allowed),'variants'=>AppKernel::inventory()->variants(trim($r->query('variant_q'))),'types'=>InventoryRules::MOVEMENT_TYPES]);
    }
    public function adjustmentForm(Request$r):Response
    {
        $u=$this->requireUser();if($u instanceof Response)return$u;$types=$this->allowedTypes($u->id??0);$type=$r->query('type',$types[0]??'adjustment_in');$permission=$this->permissionForType($type);$allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,$permission);if($allowed===[])return$this->requirePermission($u,$permission)??throw new \LogicException();$variantId=$r->integer('variant_id')?:null;return$this->adminView('admin/inventory/adjustment',['title'=>'Registrar movimiento','activeNav'=>'inventory','user'=>$u,'allBranches'=>$allowed===null,'branches'=>$this->branches($allowed),'variants'=>AppKernel::inventory()->variants(trim($r->query('variant_q'))),'variantId'=>$variantId,'units'=>$variantId===null?[]:AppKernel::inventory()->unitsForVariant($variantId),'trackingPolicy'=>$variantId===null?null:AppKernel::inventory()->trackingPolicy($variantId),'selectedType'=>$type,'types'=>$types,'variantQuery'=>trim($r->query('variant_q')),'selectedVariantLabel'=>$variantId===null?'':$this->variantLabel($variantId),'operationKey'=>bin2hex(random_bytes(16))]);
    }
    public function adjust(Request$r):Response
    {
        $u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$branch=$r->integer('branch_id');$type=$r->input('type');$permission=$this->permissionForType($type);if(($d=$this->requirePermission($u,$permission,$branch))!==null)return$d;$input=['branch_id'=>$branch,'variant_id'=>$r->integer('variant_id'),'unit_id'=>$r->integer('unit_id'),'type'=>$type,'quantity'=>$r->input('quantity'),'reason'=>$r->input('reason'),'operation_key'=>$r->input('operation_key'),'lot_code'=>$r->input('lot_code'),'expires_on'=>$r->input('expires_on'),'serial_numbers'=>$r->input('serial_numbers')];return$this->run(fn()=>AppKernel::inventoryManagement()->record($input,$u->id??0,fn(array$m)=>AppKernel::audit()->record($u->id,'inventory.'.$type,'inventory_movement',$m['id'],$branch,'success',context:['operation_key'=>$m['operation_key']])),'Movimiento registrado con trazabilidad.','/admin/inventory',$u->id,'inventory.'.$type,'inventory_movement',null,$branch);
    }
    public function threshold(Request$r):Response
    {
        $u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$branch=$r->integer('branch_id');if(($d=$this->requirePermission($u,'inventory.thresholds',$branch))!==null)return$d;$variant=$r->integer('variant_id');return$this->run(fn()=>AppKernel::inventoryManagement()->setThreshold($branch,$variant,$r->input('minimum_quantity'),$u->id??0,fn()=>AppKernel::audit()->record($u->id,'inventory.threshold.update','stock_threshold',$variant,$branch,'success')),'Existencia mínima actualizada.','/admin/inventory',$u->id,'inventory.threshold.update','stock_threshold',$variant,$branch);
    }
    public function counts(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,'inventory.counts');if($allowed===[])return$this->requirePermission($u,'inventory.counts')??throw new \LogicException();$branch=$r->integer('branch_id')?:null;if(is_array($allowed)){$branch??=$allowed[0]??null;if($branch!==null&&!in_array($branch,$allowed,true))return$this->requirePermission($u,'inventory.counts',$branch)??throw new \LogicException();}$offset=max(0,(int)$r->query('offset','0'));return$this->adminView('admin/inventory/counts',['title'=>'Conteos físicos','activeNav'=>'inventory','user'=>$u,'page'=>AppKernel::inventory()->counts($branch,25,$offset),'branchId'=>$branch,'branches'=>$this->branches($allowed)]);}
    public function createCount(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if($c=$this->requireCsrf($r,$u))return$c;$branch=$r->integer('branch_id');if($d=$this->requirePermission($u,'inventory.counts',$branch))return$d;return$this->run(function()use($r,$u,$branch):void{$id=AppKernel::inventoryManagement()->createCount($branch,self::nullable($r->input('notes')),$u->id??0,fn(int$id)=>AppKernel::audit()->record($u->id,'inventory.count.create','stock_count',$id,$branch,'success'));AppKernel::session()->flash('count_id',(string)$id);},'Conteo creado. Agrega las líneas observadas.','/admin/inventory/counts',$u->id,'inventory.count.create','stock_count',null,$branch);}
    public function countDetail(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$count=AppKernel::inventory()->count($r->integer('id'));if(!$count)return$this->adminView('admin/error',['title'=>'Conteo no encontrado','message'=>'El registro solicitado no existe.','user'=>$u],404);if($d=$this->requirePermission($u,'inventory.counts',(int)$count['branch_id']))return$d;return$this->adminView('admin/inventory/count-detail',['title'=>'Conteo #'.$count['id'],'activeNav'=>'inventory','user'=>$u,'count'=>$count,'items'=>AppKernel::inventory()->countItems((int)$count['id']),'variants'=>AppKernel::inventory()->variants(trim($r->query('variant_q')))]);}
    public function addCountItem(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if($c=$this->requireCsrf($r,$u))return$c;$count=AppKernel::inventory()->count($r->integer('id'));if(!$count)return$this->adminView('admin/error',['title'=>'Conteo no encontrado','message'=>'El registro solicitado no existe.','user'=>$u],404);if($d=$this->requirePermission($u,'inventory.counts',(int)$count['branch_id']))return$d;$id=(int)$count['id'];return$this->run(fn()=>AppKernel::inventoryManagement()->addCountLine($id,$r->integer('variant_id'),$r->input('counted_quantity'),$r->input('tracking_kind','aggregate'),$r->input('tracking_ref')),'Línea agregada al conteo.','/admin/inventory/counts/detail?id='.$id,$u->id,'inventory.count.item','stock_count',$id,(int)$count['branch_id']);}
    public function completeCount(Request$r):Response{return$this->countAction($r,'complete');}
    public function cancelCount(Request$r):Response{return$this->countAction($r,'cancel');}
    private function countAction(Request$r,string$action):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if($c=$this->requireCsrf($r,$u))return$c;$count=AppKernel::inventory()->count($r->integer('id'));if(!$count)return$this->adminView('admin/error',['title'=>'Conteo no encontrado','message'=>'El registro solicitado no existe.','user'=>$u],404);$branch=(int)$count['branch_id'];if($d=$this->requirePermission($u,'inventory.counts',$branch))return$d;$id=(int)$count['id'];return$this->run(fn()=> $action==='complete'?AppKernel::inventoryManagement()->completeCount($id,$u->id??0,fn()=>AppKernel::audit()->record($u->id,'inventory.count.complete','stock_count',$id,$branch,'success')):AppKernel::inventoryManagement()->cancelCount($id,fn()=>AppKernel::audit()->record($u->id,'inventory.count.cancel','stock_count',$id,$branch,'success')),$action==='complete'?'Conteo conciliado y movimientos registrados.':'Conteo cancelado.','/admin/inventory/counts/detail?id='.$id,$u->id,'inventory.count.'.$action,'stock_count',$id,$branch);}
    public function tracking(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,'inventory.view');if($allowed===[])return$this->requirePermission($u,'inventory.view')??throw new \LogicException();$branch=$r->integer('branch_id')?:null;if(is_array($allowed)){$branch??=$allowed[0]??null;if($branch!==null&&!in_array($branch,$allowed,true))return$this->requirePermission($u,'inventory.view',$branch)??throw new \LogicException();}$q=trim($r->query('q'));return$this->adminView('admin/inventory/tracking',['title'=>'Lotes, caducidades y series','activeNav'=>'inventory','user'=>$u,'branches'=>$this->branches($allowed),'branchId'=>$branch,'q'=>$q,'lots'=>AppKernel::inventory()->lots($branch,$q,$r->query('expiring')==='1',25,max(0,(int)$r->query('lot_offset','0'))),'serials'=>AppKernel::inventory()->serials($branch,$q,25,max(0,(int)$r->query('serial_offset','0')))]);}
    private function variantLabel(int $id):string{foreach(AppKernel::inventory()->variants('') as $variant){if((int)$variant['id']===$id)return $variant['product_name'].' · '.$variant['sku'].' · '.$variant['name'];}return 'Variante #'.$id;}
    private function permissionForType(string$type):string{return match(InventoryRules::type($type)){'initial'=>'inventory.initial','correction_in','correction_out'=>'inventory.correct',default=>'inventory.adjust'};}
    private function allowedTypes(int$userId):array{$out=[];foreach(InventoryRules::MOVEMENT_TYPES as$type){if($type==='supplier_receipt')continue;if(AppKernel::access()->accessibleBranchIdsForPermission($userId,$this->permissionForType($type))!==[])$out[]=$type;}return$out;}
    private function branches(?array$allowed):array{$rows=AppKernel::inventory()->branches();return$allowed===null?$rows:array_values(array_filter($rows,fn(array$b)=>in_array((int)$b['id'],$allowed,true)));}
    private function date(string$value):?string{$value=trim($value);if($value==='')return null;$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$d||$d->format('Y-m-d')!==$value)throw new \InvalidArgumentException('La fecha no es válida.');return$value;}
}
